CREATE DATABASE IF NOT EXISTS groczy_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE groczy_db;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS order_item;
DROP TABLE IF EXISTS `order`;
DROP TABLE IF EXISTS notification;
DROP TABLE IF EXISTS wishlist_item;
DROP TABLE IF EXISTS cart_item;
DROP TABLE IF EXISTS product;
DROP TABLE IF EXISTS category;
DROP TABLE IF EXISTS user;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE `user` (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,phone VARCHAR(30),password_hash VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'customer',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX ix_user_role(role)) ENGINE=InnoDB;
CREATE TABLE category (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,slug VARCHAR(100) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE product (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,description TEXT,brand VARCHAR(100),category_id INT NOT NULL,price DECIMAL(10,2) NOT NULL,discount_percent DECIMAL(5,2) NOT NULL DEFAULT 0,image_url VARCHAR(500),pack_size VARCHAR(80),stock INT NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE,featured BOOLEAN NOT NULL DEFAULT FALSE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX ix_product_name(name),INDEX ix_product_brand(brand),INDEX ix_product_stock(stock),CONSTRAINT fk_product_category FOREIGN KEY(category_id) REFERENCES category(id) ON UPDATE CASCADE) ENGINE=InnoDB;
CREATE TABLE cart_item (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,product_id INT NOT NULL,quantity INT NOT NULL DEFAULT 1,UNIQUE KEY uq_cart_user_product(user_id,product_id),CONSTRAINT fk_cart_user FOREIGN KEY(user_id) REFERENCES `user`(id) ON DELETE CASCADE,CONSTRAINT fk_cart_product FOREIGN KEY(product_id) REFERENCES product(id)) ENGINE=InnoDB;
CREATE TABLE wishlist_item (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,product_id INT NOT NULL,UNIQUE KEY uq_wishlist_user_product(user_id,product_id),CONSTRAINT fk_wishlist_user FOREIGN KEY(user_id) REFERENCES `user`(id) ON DELETE CASCADE,CONSTRAINT fk_wishlist_product FOREIGN KEY(product_id) REFERENCES product(id)) ENGINE=InnoDB;
CREATE TABLE notification (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,product_id INT NOT NULL,message VARCHAR(300) NOT NULL,`read` BOOLEAN NOT NULL DEFAULT FALSE,event_key VARCHAR(100) NOT NULL UNIQUE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX ix_notification_user_read(user_id,`read`),CONSTRAINT fk_notification_user FOREIGN KEY(user_id) REFERENCES `user`(id) ON DELETE CASCADE,CONSTRAINT fk_notification_product FOREIGN KEY(product_id) REFERENCES product(id)) ENGINE=InnoDB;
CREATE TABLE `order` (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,address TEXT NOT NULL,phone VARCHAR(30) NOT NULL,subtotal DECIMAL(10,2) NOT NULL,discount DECIMAL(10,2) NOT NULL DEFAULT 0,delivery_fee DECIMAL(10,2) NOT NULL DEFAULT 0,total DECIMAL(10,2) NOT NULL,payment_method VARCHAR(30) NOT NULL,payment_status VARCHAR(30) NOT NULL DEFAULT 'Not Paid',status VARCHAR(30) NOT NULL DEFAULT 'Pending',INDEX ix_order_user_date(user_id,created_at),INDEX ix_order_status(status),CONSTRAINT fk_order_user FOREIGN KEY(user_id) REFERENCES `user`(id)) ENGINE=InnoDB;
CREATE TABLE order_item (id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,product_id INT NULL,product_name VARCHAR(160) NOT NULL,unit_price DECIMAL(10,2) NOT NULL,quantity INT NOT NULL,item_subtotal DECIMAL(10,2) NOT NULL,CONSTRAINT fk_orderitem_order FOREIGN KEY(order_id) REFERENCES `order`(id) ON DELETE CASCADE,CONSTRAINT fk_orderitem_product FOREIGN KEY(product_id) REFERENCES product(id) ON DELETE SET NULL) ENGINE=InnoDB;
INSERT INTO category(name,slug) VALUES ('Fruits','fruits'),('Vegetables','vegetables'),('Dairy and Eggs','dairy-and-eggs'),('Rice and Grains','rice-and-grains'),('Pulses and Lentils','pulses-and-lentils'),('Snacks','snacks'),('Beverages','beverages'),('Bakery','bakery'),('Personal Care','personal-care'),('Household Essentials','household-essentials');
